  ('5507', 'WI-07', '02f64fe0-6d68-4c8b-b42b-3c801453277a', 'Alfonso', 'AP race call for the 2026-11-03 general election: Michael Alfonso (GOP) 56.08%, 186,035 votes; called 2026-11-04T04:02:12.771Z. AP race 20261103WI50064, https://interactives.apelections.org/election-results/data-live/2026-11-03/ (read 2026-11-04). UNOFFICIAL - this is a race call, not the state canvass.'),
  ('5508', 'WI-08', 'ace7d969-5a0b-40e6-84e5-b54f401623b9', 'Wied', 'AP race call for the 2026-11-03 general election: Tony Wied (GOP) 53.92%, 177,258 votes; called 2026-11-04T04:01:22.295Z. AP race 20261103WI50068, https://interactives.apelections.org/election-results/data-live/2026-11-03/ (read 2026-11-04). UNOFFICIAL - this is a race call, not the state canvass.'),
  ('5600', 'WY-00', 'ef7cb9bc-d200-4b74-b848-2f24ea3e9114', 'Gray', 'AP race call for the 2026-11-03 general election: Chuck Gray (GOP) 54.52%, 99,891 votes; called 2026-11-04T04:40:29.036Z. AP race 20261103WY51401, https://interactives.apelections.org/election-results/data-live/2026-11-03/ (read 2026-11-04). UNOFFICIAL - this is a race call, not the state canvass.')
;

-- Every US House candidate row on the 2026-11-03 ballot.
CREATE TEMP TABLE house_2026 ON COMMIT DROP AS
SELECT d.geo_id, upper(d.state) AS st, r.id AS race_id, rc.id AS rc_id,
       p.full_name, p.last_name, rc.result AS result_before, rc.result_source AS source_before
  FROM essentials.races r
  JOIN essentials.elections e ON e.id = r.election_id
  JOIN essentials.offices   o ON o.id = r.office_id
  JOIN essentials.districts d ON d.id = o.district_id
  JOIN essentials.race_candidates rc ON rc.race_id = r.id
  JOIN essentials.politicians p ON p.id = rc.politician_id
 WHERE e.election_date = DATE '2026-11-03' AND d.district_type = 'NATIONAL_LOWER';

-- 🔴 THE PIN IS SELF-CHECKING: the id must sit in the stated district AND carry the stated
-- surname. Either disagreeing drops the row, and the count gate below turns that into a raise.
CREATE TEMP TABLE house_winners ON COMMIT DROP AS
SELECT a.seat, a.src, h.rc_id, h.race_id, h.full_name, h.result_before, h.source_before
  FROM ap_house_calls a
  JOIN house_2026 h ON h.rc_id = a.rc_id
                   AND h.geo_id = a.geo_id
                   AND h.last_name = a.our_last;

UPDATE essentials.race_candidates rc
   SET result           = 'won',
       result_certainty = 'called',
       result_source    = CASE
         WHEN w.source_before IS NULL OR btrim(w.source_before) = '' THEN w.src
         ELSE w.src || ' || PRIOR RESULT ' || quote_literal(coalesce(w.result_before, '(none)'))
              || ', SOURCED TO: ' || w.source_before
       END
  FROM house_winners w
 WHERE rc.id = w.rc_id
   AND rc.result IS DISTINCT FROM 'won';

DO $$
DECLARE
  v_calls bigint; v_matched bigint; v_won bigint; v_races bigint; v_dupe bigint;
  v_cert bigint; v_tx22 bigint; v_total bigint; v_overwritten bigint; v_lost_src bigint;
BEGIN
  SELECT count(DISTINCT race_id) INTO v_total FROM house_2026;
  IF v_total <> 435 THEN
    RAISE EXCEPTION 'CC_0350: expected 435 US House races on 2026-11-03, found %', v_total;
  END IF;

  SELECT count(*) INTO v_calls FROM ap_house_calls;
  IF v_calls <> 377 THEN
    RAISE EXCEPTION 'CC_0350: expected 377 AP calls in this file, found %', v_calls;
  END IF;

  -- 🔴 A PIN THAT DOES NOT RESOLVE RETURNS A SMALLER SET, SILENTLY. This is the count that
  -- caught New Mexico in CC_0339, and it is the same shape here.
  SELECT count(*) INTO v_matched FROM house_winners;
  IF v_matched <> 377 THEN
    RAISE EXCEPTION 'CC_0350: % winner(s) resolved, expected 377 -- a pin that misses its district or surname drops out with no error', v_matched;
  END IF;

  -- 🔴 ONE WINNER PER RACE.
  SELECT count(*) INTO v_dupe FROM (
    SELECT race_id FROM house_winners GROUP BY race_id HAVING count(*) > 1) x;
  IF v_dupe <> 0 THEN
    RAISE EXCEPTION 'CC_0350: % race(s) resolved more than one winner', v_dupe;
  END IF;

  SELECT count(*) INTO v_won
    FROM essentials.race_candidates rc JOIN house_2026 h ON h.rc_id = rc.id
   WHERE rc.result = 'won';
  IF v_won <> 377 THEN
    RAISE EXCEPTION 'CC_0350: expected 377 House rows marked won, found %', v_won;
  END IF;

  SELECT count(DISTINCT h.race_id) INTO v_races
    FROM essentials.race_candidates rc JOIN house_2026 h ON h.rc_id = rc.id
   WHERE rc.result = 'won';
  IF v_races <> 377 THEN
    RAISE EXCEPTION 'CC_0350: 377 winners span % races, not 377', v_races;
  END IF;

  -- 🔴 TX-22 MUST STAY EMPTY. AP's winner there is a person we do not hold.
  SELECT count(*) INTO v_tx22
    FROM essentials.race_candidates rc JOIN house_2026 h ON h.rc_id = rc.id
   WHERE h.geo_id = '4822' AND rc.result = 'won';
  IF v_tx22 <> 0 THEN
    RAISE EXCEPTION 'CC_0350: TX-22 has % winner row(s); AP called it for Trever Nehls, whom this database does not hold', v_tx22;
  END IF;

  -- 🔴 NOTHING MAY CLAIM TO BE CERTIFIED.
  SELECT count(*) INTO v_cert
    FROM essentials.race_candidates rc JOIN house_2026 h ON h.rc_id = rc.id
   WHERE rc.result_certainty = 'certified';
  IF v_cert <> 0 THEN
    RAISE EXCEPTION 'CC_0350: % House row(s) claim certification', v_cert;
  END IF;

  -- 🔴 THE OVERWRITTEN CITATION MUST STILL BE IN THE ROW. 51 rows had a prior
  -- result_source; every one must still contain it, or this migration destroyed evidence.
  SELECT count(*) INTO v_overwritten
    FROM house_winners WHERE source_before IS NOT NULL AND btrim(source_before) <> '';
  IF v_overwritten <> 51 THEN
    RAISE EXCEPTION 'CC_0350: expected 51 rows carrying a prior result_source, found %', v_overwritten;
  END IF;

  SELECT count(*) INTO v_lost_src
    FROM essentials.race_candidates rc JOIN house_winners w ON w.rc_id = rc.id
   WHERE w.source_before IS NOT NULL AND btrim(w.source_before) <> ''
     AND position(w.source_before in rc.result_source) = 0;
  IF v_lost_src <> 0 THEN
    RAISE EXCEPTION 'CC_0350: % row(s) lost the ballot-qualification citation they used to carry', v_lost_src;
  END IF;

  RAISE NOTICE 'CC_0350 OK: % of 435 US House races recorded as called; 57 uncalled, TX-22 withheld', v_won;
END $$;
